    principals_bind: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description ZITADEL `sub` claim of the principal to bind. */
                    oidc_sub: string;
                    /** @description ZITADEL issuer URL. */
                    oidc_issuer: string;
                    /** @description Display name shown to other principals. */
                    display_name: string;
                    /**
                     * @description Only `sub_user` is accepted; owner is provisioned by bootstrap.
                     * @enum {string}
                     */
                    role: "sub_user";
                };
            };
        };
        responses: {
            /** @description Principal already bound — idempotent re-bind. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** Format: uuid */
                        id: string;
                        /** @enum {boolean} */
                        created: false;
                    };
                };
            };
            /** @description Principal created and bound. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** Format: uuid */
                        id: string;
                        /** @enum {boolean} */
                        created: true;
                    };
                };
            };
            /** @description Invalid request body. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Unauthorized. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Sub-user is not allowed to call admin endpoints. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
